const now = new Date();
const pad = (n) => String(n).padStart(2, "0");
const timestamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth() + 1)}${pad(now.getUTCDate())}_${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}`;

return [{
  json: {
    backupTimestamp: timestamp,
    backupFolder: `n8n_backup_${timestamp}`,
    n8nBaseUrl: $env.N8N_URL || "http://localhost:5678",
    apiKey: $env.N8N_API_KEY
  }
}];

const backupMeta = $("Initialize Backup Context").first().json;
const workflowsResponse = $("Export All Workflows").first().json.data || [];
const rawCredentials = $("Export Credentials List").first().json.data || [];

// Security Rule: Strip every credential property except non sensitive metadata
const sanitizedCredentials = rawCredentials.map(c => ({
  id: c.id,
  name: c.name,
  type: c.type,
  createdAt: c.createdAt,
  updatedAt: c.updatedAt
}));

const manifest = {
  backupTimestamp: backupMeta.backupTimestamp,
  totalWorkflows: workflowsResponse.length,
  activeWorkflows: workflowsResponse.filter(w => w.active).length,
  totalCredentials: sanitizedCredentials.length,
  exportedAt: new Date().toISOString(),
  workflows: workflowsResponse,
  credentialsInventory: sanitizedCredentials
};

const formattedJson = JSON.stringify(manifest, null, 2);
const binaryData = Buffer.from(formattedJson, "utf8").toString("base64");

return [{
  json: {
    status: "SUCCESS",
    backupFolder: backupMeta.backupFolder,
    fileName: `n8n_manifest_${backupMeta.backupTimestamp}.json`,
    workflowsCount: workflowsResponse.length,
    credentialsCount: sanitizedCredentials.length,
    summary: `Backup complete: ${workflowsResponse.length} workflows and ${sanitizedCredentials.length} credential references preserved.`
  },
  binary: {
    data: {
      data: binaryData,
      mimeType: "application/json",
      fileName: `n8n_manifest_${backupMeta.backupTimestamp}.json`
    }
  }
}];
